solution.exercise.c:
#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
bool account_open(bank_account*a){if(a->is_open)return false;a->is_open=true;a->balance=0;return true;}bool account_close(bank_account*a){if(!a->is_open)return false;a->is_open=false;a->balance=0;return true;}bool account_balance(const bank_account*a,int64_t*out){if(!a->is_open)return false;*out=a->balance;return true;}bool account_deposit(bank_account*a,int64_t n){if(!a->is_open||n<=0||a->balance>INT64_MAX-n)return false;a->balance+=n;return true;}bool account_withdraw(bank_account*a,int64_t n){if(!a->is_open||n<=0||n>a->balance)return false;a->balance-=n;return true;}

